import pandas as pd
import sys

# --- Configuration ---
# Use the output file name from the scraper script
input_csv_file = 'exoneration_list_detailed.csv'
# --- End Configuration ---

print(f"Analyzing '{input_csv_file}' for duplicate names...")

try:
    # Read the CSV file generated by the scraper
    df = pd.read_csv(input_csv_file)
    print(f"Successfully read {len(df)} records from the file.")

    # Check if the 'Name' column exists
    if 'Name' not in df.columns:
        print(f"Error: 'Name' column not found in {input_csv_file}. Please check the CSV file.")
        sys.exit(1)

    # --- Find Duplicate Names ---
    # Count occurrences of each name
    name_counts = df['Name'].value_counts()

    # Filter to get only names that appear more than once
    duplicate_names = name_counts[name_counts > 1]

    # --- Report Results ---
    if duplicate_names.empty:
        print("\nNo duplicate names found in the 'Name' column.")
    else:
        print(f"\nFound {len(duplicate_names)} names that appear more than once:")
        print("-" * 30)
        # Get the list of names that are duplicates
        duplicate_name_list = duplicate_names.index.tolist()

        # Filter the original DataFrame to get all rows for these duplicate names
        duplicate_rows = df[df['Name'].isin(duplicate_name_list)].copy() # Use .copy() to avoid SettingWithCopyWarning

        # Sort the results by name for easier comparison
        duplicate_rows.sort_values(by='Name', inplace=True)

        # Display the duplicate names and their details
        print("Details of duplicate entries:")
        print(duplicate_rows.to_markdown(index=False, numalign="left", stralign="left")) # Use Markdown for better formatting in supported terminals

        # Also print the summary count
        print("\nDuplicate Name Counts:")
        print(duplicate_names.to_markdown(numalign="left", stralign="left"))


except FileNotFoundError:
    print(f"Error: The file '{input_csv_file}' was not found.")
    print("Please ensure the scraper script ran successfully and created the file.")
except pd.errors.EmptyDataError:
    print(f"Error: The file '{input_csv_file}' is empty.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")

print("\nAnalysis complete.")